from taf.rfrl.procedures.resources.python.logger import log_step

from taf.rfrl.procedures.resources.python.sw_update.exceptions import InvalidSwVersion
from taf.rfrl.procedures.resources.python.sw_update.sw_version.gnb_sw_version import \
    GnbSwVersion
from taf.rfrl.procedures.resources.python.sw_update.sw_version.sbts_sw_version import \
    SbtsSwVersion
from taf.rfrl.procedures.resources.python.sw_update.sw_version.sbts_knife_sw_version import \
    SbtsKnifeSwVersion


class SwVersionFactory:
    """ Creates SwVersion instances. """

    @classmethod
    def create_sw_version(cls, number):
        """
        Creates SwVersion with given raw number.

        :param number: raw SW version number, i.e. '5G21A_GNB_0011_000800_000315'
        :type number: str
        :return: SwVersion instance
        :rtype: SwVersion
        """
        if number.startswith('5G'):
            log_step('Creating GnbSwVersion {}'.format(number))
            return GnbSwVersion(raw=number)
        elif number.startswith('SBTS'):
            if len(number.split('_')[-1]) == 7:
                log_step('Creating SbtsKnifeSwVersion {}'.format(number))
                return SbtsKnifeSwVersion(raw=number)
            else:
                log_step('Creating SbtsSwVersion {}'.format(number))
                return SbtsSwVersion(raw=number)
        else:
            raise InvalidSwVersion("SW version number must start with '5G' or 'SBTS'")
